    {
      "id": "Ed615ac401076e86e",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A Resolução ANP nº 817/2020 trata das atividades de descomissionamento de instalações de exploração e produção de petróleo e gás natural e reúne, em instrumento único, processos antes dispersos.",
          "trechos": [
            "Ed615ac401076e86e:0:699",
            "Ed615ac401076e86e:699:1397"
          ],
          "condicoes": [
            "Aplicável ao descomissionamento de instalações de E&P no contexto regulatório brasileiro descrito pela fonte."
          ],
          "limites": [
            "Os trechos fornecidos não detalham procedimentos específicos de drenagem, flushing, purga, inertização ou limpeza.",
            "A fonte resume o conteúdo regulatório, sem reproduzir integralmente os requisitos da resolução."
          ]
        },
        {
          "proposicao": "A resolução estabelece requisitos técnicos-ambientais, de segurança operacional e de navegação para o descomissionamento.",
          "trechos": [
            "Ed615ac401076e86e:1397:2094"
          ],
          "condicoes": [
            "No âmbito do instrumento regulatório citado."
          ],
          "limites": [
            "Os requisitos não são discriminados nos trechos recuperados.",
            "Não há detalhamento direto sobre critérios de limpeza e descontaminação de sistemas."
          ]
        },
        {
          "proposicao": "O conceito de PDI único incorpora avaliação comparativa de alternativas de descomissionamento, considerando questões técnicas, ambientais, de segurança e econômicas para definição do plano aplicável à instalação.",
          "trechos": [
            "Ed615ac401076e86e:1397:2094",
            "Ed615ac401076e86e:2094:2424"
          ],
          "condicoes": [
            "Na elaboração do Programa de Descomissionamento de Instalações mencionado pela fonte."
          ],
          "limites": [
            "Os trechos não explicitam como inventários, isolamento ou descontaminação entram nessa comparação.",
            "A fonte não apresenta metodologia operacional passo a passo."
          ]
        }
      ]
    },
    {
      "id": "Eaefbc9325a8aea88",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "As práticas de descomissionamento vêm evoluindo e a análise por vários segmentos é apresentada como ferramenta relevante ao processo decisório.",
          "trechos": [
            "Eaefbc9325a8aea88:0:698",
            "Eaefbc9325a8aea88:698:1396"
          ],
          "condicoes": [
            "No contexto de projetos de descomissionamento tecnologicamente mais complexos."
          ],
          "limites": [
            "A fonte não detalha segmentos, critérios operacionais nem etapas específicas de parada, limpeza ou inertização."
          ]
        },
        {
          "proposicao": "Na etapa de desmantelamento e gestão de resíduos, a formação de uma cadeia logística reversa é tratada como aspecto importante, incluindo reaproveitamento de sucata ferrosa e reutilização de materiais remanescentes de embarcações.",
          "trechos": [
            "Eaefbc9325a8aea88:698:1396"
          ],
          "condicoes": [
            "Relacionada ao desmantelamento e à gestão de resíduos após a retirada de serviço."
          ],
          "limites": [
            "Os trechos não especificam requisitos prévios de descontaminação para viabilizar reutilização ou reciclagem.",
            "A importância indicada é explicação técnica, não obrigação normativa nos trechos."
          ]
        },
        {
          "proposicao": "A ideia de reciclagem e revenda de equipamentos de segunda mão é apresentada como passível de replicação no Brasil, com potencial aproveitamento de estaleiros brasileiros para desmonte e restauração de plataformas.",
          "trechos": [
            "Eaefbc9325a8aea88:698:1396",
            "Eaefbc9325a8aea88:1396:2094"
          ],
          "condicoes": [
            "Como possibilidade de desenvolvimento de mercado e de reutilização de equipamentos."
          ],
          "limites": [
            "A fonte fala em potencial e possibilidade, não em prática consolidada ou exigência geral no Brasil.",
            "Não aborda compatibilidade técnica dos equipamentos reutilizados nem critérios de limpeza associados."
          ]
        }
      ]
    },
    {
      "id": "E243b5a6abad35913",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Diante de regulamentos dispersos e da ausência de normativos específicos apontada pela fonte, é apresentada a necessidade de metodologia com critérios de avaliação para remoção ou permanência de instalações, equilibrando proteção ambiental, risco operacional e viabilidade técnica e econômica.",
          "trechos": [
            "E243b5a6abad35913:0:692",
            "E243b5a6abad35913:692:1392"
          ],
          "condicoes": [
            "No processo decisório sobre alternativas de descomissionamento offshore."
          ],
          "limites": [
            "A formulação é uma necessidade metodológica indicada pela fonte, não um requisito jurídico brasileiro completo.",
            "Os trechos não definem como aplicar esses critérios a tarefas específicas de limpeza e descontaminação."
          ]
        },
        {
          "proposicao": "A avaliação comparativa multicritério é descrita como metodologia semiquantitativa, multidisciplinar e ajustável ao cenário ambiental e legal, com intenção de reduzir subjetividade no processo decisório.",
          "trechos": [
            "E243b5a6abad35913:692:1392"
          ],
          "condicoes": [
            "Quando critérios e pesos são definidos, reavaliados e validados com participação de diferentes áreas e partes interessadas."
          ],
          "limites": [
            "A fonte não fornece a formulação matemática nem pesos aplicáveis.",
            "O método é apresentado como exemplo, não como padrão obrigatório universal."
          ]
        },
        {
          "proposicao": "Guias estrangeiros citados pela fonte estruturam a avaliação comparativa em cinco critérios principais: segurança, meio ambiente, técnica, social e econômico.",
          "trechos": [
            "E243b5a6abad35913:1392:2091",
            "E243b5a6abad35913:2091:2468"
          ],
          "condicoes": [
            "No contexto das orientações do Reino Unido mencionadas pela fonte."
          ],
          "limites": [
            "Trata-se de referência estrangeira e benchmarking, não requisito brasileiro por si só.",
            "Os trechos não detalham subcritérios ligados a isolamento, drenagem, flushing ou purga."
          ]
        }
      ]
    },
    {
      "id": "E824e160f24ddc5f9",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O descomissionamento é definido como conjunto de atividades relacionadas à estagnação das operações em um campo quando a produção já não sustenta a economicidade do ativo, ocorrendo em geral na etapa final do projeto.",
          "trechos": [
            "E824e160f24ddc5f9:0:700"
          ],
          "condicoes": [
            "Segundo a definição e enquadramento geral apresentados pela fonte."
          ],
          "limites": [
            "A definição é geral e não específica para FPSO nem para tarefas de limpeza e descontaminação."
          ]
        },
        {
          "proposicao": "Entre os objetivos do procedimento estão abandono de poços, remoção, desmantelamento e possível reutilização da estrutura ou plataforma.",
          "trechos": [
            "E824e160f24ddc5f9:0:700"
          ],
          "condicoes": [
            "Como descrição geral do escopo de descomissionamento apresentada pela fonte."
          ],
          "limites": [
            "A fonte não explicita condições técnicas para reutilização nem critérios de aceitação após limpeza."
          ]
        },
        {
          "proposicao": "Previsão de data e custos de descomissionamento devem constar no Plano de Desenvolvimento do campo, e estimativas de custo variam entre operadoras em função de experiência, profundidade, período do descomissionamento e risco de acidentes em atividades como corte, solda e movimentação de cargas.",
          "trechos": [
            "E824e160f24ddc5f9:0:700",
            "E824e160f24ddc5f9:700:1398"
          ],
          "condicoes": [
            "No Brasil, quanto ao conteúdo do Plano de Desenvolvimento mencionado pela fonte.",
            "Na estimativa de custos, considerando variáveis e riscos citados."
          ],
          "limites": [
            "Os trechos não apresentam método de cálculo de custos.",
            "Os acidentes mencionados são exemplos de fatores de gasto adicional, não uma lista exaustiva de riscos."
          ]
        }
      ]
    },
    {
      "id": "Ea39e9a92f4068189",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No descomissionamento do topside, deve-se observar o destino dos equipamentos de processamento e da estrutura do convés.",
          "trechos": [
            "Ea39e9a92f4068189:692:1385"
          ],
          "condicoes": [
            "No contexto do descomissionamento da parte superior da plataforma descrita pela fonte."
          ],
          "limites": [
            "A fonte não define critérios técnicos para seleção entre reutilização, descarte ou reciclagem.",
            "Não há detalhamento das etapas de limpeza prévia desses equipamentos."
          ]
        },
        {
          "proposicao": "O tamponamento e abandono do poço são apresentados como primeira etapa necessária para descomissionar um sistema de produção, por ser imprescindível o isolamento para impedir vazamentos de óleo e gás para o mar.",
          "trechos": [
            "Ea39e9a92f4068189:692:1385",
            "Ea39e9a92f4068189:1385:2082"
          ],
          "condicoes": [
            "No encerramento da atividade de poços dentro do sistema de produção."
          ],
          "limites": [
            "O trecho aborda isolamento de poços, não procedimentos detalhados de isolamento de vasos, tubulações ou tanques do FPSO.",
            "Não informa métodos, barreiras ou critérios de verificação."
          ]
        },
        {
          "proposicao": "Durante o contrato de exploração e produção, a ANP exige o envio de documentos relativos a etapas como construção, operação, intervenção e abandono de poços.",
          "trechos": [
            "Ea39e9a92f4068189:1385:2082"
          ],
          "condicoes": [
            "No decorrer do contrato de E&P referido pela fonte."
          ],
          "limites": [
            "O trecho não identifica quais documentos são exigidos nem seu conteúdo.",
            "A obrigação é mencionada em termos gerais e vinculada a poços."
          ]
        }
      ]
    }
  ],
